alter table memberships add column credential_policy text not null default 'case-sensitive-v1';
alter table private.provisioning add column details jsonb not null default '{}';
alter table private.provisioning add column lease_until timestamptz;
create function public.reserve_account(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare s uuid:=coalesce(private.school(),(p->>'schoolId')::uuid);v_kind text:=p->>'role';lim int;n int;res private.provisioning;existing uuid;ln text:=lower(p->>'loginId');canonical_identity text; suffix int:=1;begin
if not(private.role()='owner' and v_kind='administrator' or private.role()='administrator' and v_kind in ('teacher','student') or private.role()='teacher' and v_kind='student' and private.assigned((p->>'classId')::uuid))then raise exception 'FORBIDDEN' using errcode='42501';end if;
if private.role()<>'owner' then perform private.require_access(s,true);end if;
canonical_identity:=case when v_kind='student'then case when p->>'admissionNumber'is not null then 'admission:'||(p->>'admissionNumber')else 'roster:'||(p->>'classId')||':'||lower(trim(p->>'roll'))end else p->>'identityKey'end;select * into res from private.provisioning where school_id=s and identity_key=canonical_identity for update;if found then if v_kind='student'and lower(trim(res.details->>'name'))<>lower(trim(p->>'name'))then return jsonb_build_object('state','conflict');end if;return jsonb_build_object('id',res.id,'state',case when res.state='active'then 'existing'else res.state end,'loginId',res.details->>'loginId');end if;
select case when v_kind='teacher'then teacher_limit else student_limit end into lim from public.subscriptions where school_id=s and now()between starts_at and ends_at for update;if not found then raise exception 'SUBSCRIPTION_EXPIRED';end if;select * into res from private.provisioning where school_id=s and identity_key=canonical_identity for update;if found then if v_kind='student'and lower(trim(res.details->>'name'))<>lower(trim(p->>'name'))then return jsonb_build_object('state','conflict');end if;return jsonb_build_object('id',res.id,'state',case when res.state='active'then 'existing'else res.state end,'loginId',res.details->>'loginId');end if;
if v_kind='student' then
if p->>'admissionNumber' is not null then select student_id into existing from public.student_registry where school_id=s and admission_number=p->>'admissionNumber';end if;
if existing is null then select e.student_id into existing from public.enrollments e join public.memberships m on m.id=e.student_id where e.school_id=s and e.class_id=(p->>'classId')::uuid and e.roll=lower(trim(p->>'roll'));if existing is not null and not exists(select 1 from public.memberships where id=existing and lower(trim(display_name))=lower(trim(p->>'name')))then return jsonb_build_object('state','conflict');end if;end if;
if existing is not null then perform private.audit(s,'account.reused',existing);return jsonb_build_object('id',existing,'state','existing');end if;end if;
select count(*)into n from public.memberships where school_id=s and role=v_kind and active;n:=n+(select count(*)from private.provisioning where school_id=s and provisioning.kind=v_kind and state<>'active');if v_kind<>'administrator' and n>=lim then raise exception 'QUOTA_EXCEEDED';end if;
if ln !~ '^[a-z0-9._-]{3,64}$' or ln in ('admin','owner','root','support')then raise exception 'INVALID_LOGIN';end if;
while exists(select 1 from private.login_identifiers where school_id=s and normalized=ln)or exists(select 1 from private.provisioning where school_id=s and lower(details->>'loginId')=ln)loop suffix:=suffix+1;ln:=left(lower(p->>'loginId'),60)||'.'||suffix;end loop;
insert into private.provisioning(id,school_id,actor_id,kind,identity_key,details)values(gen_random_uuid(),s,auth.uid(),v_kind,canonical_identity,p||jsonb_build_object('loginId',ln))returning * into res;perform private.audit(s,'account.reserved',res.id);return jsonb_build_object('id',res.id,'state',res.state,'loginId',ln);end$$;
create function public.runtime_provision_claim(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare r private.provisioning;begin update private.provisioning set lease_until=now()+interval '2 minutes',updated_at=now()where id=(p->>'id')::uuid and state<>'active' and(lease_until is null or lease_until<now())returning * into r;return case when r.id is null then null else to_jsonb(r)end;end$$;
create function public.runtime_provision_auth(p jsonb)returns void language sql security definer set search_path='' as $$update private.provisioning set state='auth_created',auth_id=(p->>'id')::uuid,updated_at=now()where id=(p->>'id')::uuid and state in ('reserved','failed')$$;
create function public.runtime_provision_activate(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare r private.provisioning;begin select * into r from private.provisioning where id=(p->>'id')::uuid for update;if r.state='active'then return;end if;if r.state<>'auth_created' then raise exception 'AUTH_NOT_CREATED';end if;if not exists(select 1 from public.memberships actor join public.schools sc on sc.id=r.school_id where actor.id=r.actor_id and actor.active and sc.status='active'and(actor.role='owner'and r.kind='administrator'or actor.school_id=r.school_id and(actor.role='administrator'and r.kind in('teacher','student')or actor.role='teacher'and r.kind='student'and exists(select 1 from public.teacher_assignments where teacher_id=actor.id and class_id=(r.details->>'classId')::uuid))))then raise exception 'PROVISIONING_AUTHORIZATION_REVOKED'using errcode='42501';end if;
insert into public.memberships(id,school_id,role,display_name,must_change_password,credential_policy)values(r.id,r.school_id,r.kind,r.details->>'name',r.kind<>'student',case when r.kind='student'then 'name-roster-ascii-fold-v1'else 'case-sensitive-v1'end)on conflict(id)do nothing;
insert into private.login_identifiers values(r.school_id,lower(r.details->>'loginId'),r.details->>'loginId',r.id,true)on conflict do nothing;
if r.kind='student'then insert into public.student_registry values(r.id,r.school_id,r.details->>'admissionNumber')on conflict do nothing;insert into public.enrollments values(r.school_id,(r.details->>'classId')::uuid,r.id,r.details->>'roll',true)on conflict do nothing;end if;
update private.provisioning set state='active',lease_until=null,updated_at=now()where id=r.id;insert into public.audit_events(school_id,actor_id,actor_role,subject_id,action)select r.school_id,r.actor_id,m.role,r.id,'account.created'from public.memberships m where m.id=r.actor_id;end$$;
create function public.runtime_provision_failed(p jsonb)returns void language sql security definer set search_path='' as $$update private.provisioning set lease_until=null,error_code=p->>'code',updated_at=now()where id=(p->>'id')::uuid$$;
create or replace function public.runtime_login_lookup(p jsonb)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',m.id,'credentialVersion',m.credential_version,'mustChangePassword',m.must_change_password,'role',m.role,'policy',m.credential_policy)from private.login_identifiers l join public.memberships m on m.id=l.user_id join public.schools s on s.id=m.school_id where s.code=lower(p->>'schoolCode') and l.normalized=lower(p->>'loginId') and l.current and m.active and s.status='active'$$;
create function public.support_metadata(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();u uuid:=(p->>'studentId')::uuid;i uuid;begin if not exists(select 1 from private.sessions where user_id=auth.uid()and revoked_at is null and expires_at>now()and reauthenticated_at>now()-interval '5 minutes')then raise exception 'RECENT_REAUTH_REQUIRED'using errcode='42501';end if;if not private.student_access(u)or length(coalesce(p->>'reason',''))=0 then raise exception 'FORBIDDEN' using errcode='42501';end if;
insert into private.support_sessions(school_id,actor_id,student_id,reason,expires_at)values(s,auth.uid(),u,p->>'reason',now()+interval '15 minutes')returning id into i;perform private.audit(s,'account.support.started',u,p->>'reason');return jsonb_build_object('id',i,'expiresAt',now()+interval '15 minutes','scope','operational-metadata','accountActive',(select active from public.memberships where id=u),'sessionCount',(select count(*)from private.sessions where user_id=u and revoked_at is null and expires_at>now()),'provisioningState',(select state from private.provisioning where id=u));end$$;
revoke execute on function public.reserve_account(jsonb),public.support_metadata(jsonb)from public,anon,authenticated;grant execute on function public.reserve_account(jsonb),public.support_metadata(jsonb)to authenticated;
revoke execute on function public.runtime_provision_claim(jsonb),public.runtime_provision_auth(jsonb),public.runtime_provision_activate(jsonb),public.runtime_provision_failed(jsonb)from public,anon,authenticated;grant execute on function public.runtime_provision_claim(jsonb),public.runtime_provision_auth(jsonb),public.runtime_provision_activate(jsonb),public.runtime_provision_failed(jsonb)to service_role;
